WITH filtered AS (SELECT id, customer_id, device, browser, started_at, LENGTH(device) AS device_length, COALESCE(browser, 'OTHER') AS resolved_browser FROM sessions WHERE country IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM filtered), islands AS (SELECT id, customer_id, device, started_at, resolved_browser, SUM(new_group_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT burst_id, customer_id, APPROX_PERCENTILE(burst_id, 0.95) AS burst_id_p95, APPROX_PERCENTILE(burst_id, 0.5) AS burst_id_p50, PERCENTILE_APPROX(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles, COUNT(*) FILTER (WHERE device = 'desktop') AS desktop_rows, SORT_ARRAY(COLLECT_SET(device)) AS device_list, PERCENTILE_APPROX(burst_id, 0.95) AS burst_id_p95_2, PERCENT_RANK() OVER (PARTITION BY burst_id ORDER BY PERCENTILE_APPROX(burst_id, 0.95) DESC) AS burst_id_p95_2_percent_rank FROM islands GROUP BY burst_id, customer_id ORDER BY desktop_rows DESC NULLS FIRST;
